import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../../src/app.mjs'

// In-process fake of the downstream pricing gateway (priceOf(sku) -> euros).
const prices = { A: 10, B: 40, C: 9.99, D: 50 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, json, id string, total', async () => {
  const res = await post({ items: [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.deepEqual(body.items, [{ sku: 'A', qty: 2 }, { sku: 'B', qty: 1 }])
  assert.equal(body.total, 60)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const body = await (await post({ items: [{ sku: 'D', qty: 2 }] })).json()
  assert.equal(body.total, 100)
})

test('POST /orders: total above 100 gets 10% discount', async () => {
  const body = await (await post({ items: [{ sku: 'D', qty: 3 }] })).json()
  assert.equal(body.total, 135)
})

test('POST /orders: total is floored, not rounded', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — Math.floor drops cents (29.97 -> 29)
  const body = await (await post({ items: [{ sku: 'C', qty: 3 }] })).json()
  assert.equal(body.total, 29)
})

test('POST /orders: ids are distinct', async () => {
  const a = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  assert.notEqual(a.id, b.id)
})

test('POST /orders: 400 for empty items, missing items, non-array, invalid JSON', async () => {
  for (const res of [
    await post({ items: [] }),
    await post({}),
    await post({ items: 'x' }),
    await post(null, 'not json'),
  ]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders: unknown sku / missing qty yields null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — no validation; NaN total serialises as null, order still 201
  const res = await post({ items: [{ sku: 'ZZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('GET /orders/:id returns a created order', async () => {
  const created = await (await post({ items: [{ sku: 'A', qty: 1 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/:id for unknown id returns 200 with error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — "not found" is returned with status 200, not 404
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and wrong methods return 404 no route', async () => {
  for (const [method, path] of [['GET', '/'], ['GET', '/orders'], ['DELETE', '/orders/1'], ['PUT', '/orders'], ['GET', '/orders/1/items']]) {
    const res = await fetch(`${base}${path}`, { method })
    assert.equal(res.status, 404, `${method} ${path}`)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
EOF
